import json, subprocess, sys
prompt = sys.argv[1]
argv = ['pi', '--provider', 'zai', '--model', 'glm-5.2', '--mode', 'json',
        '--no-session', '--no-extensions', '--no-context-files', '--offline',
        '-a', '-p', '--', prompt]
proc = subprocess.run(argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
ti = to = 0
for line in proc.stdout.decode('utf-8', 'replace').splitlines():
    line = line.strip()
    if not line:
        continue
    try:
        evt = json.loads(line)
    except ValueError:
        continue
    if not isinstance(evt, dict) or evt.get('type') != 'message_end':
        continue
    msg = evt.get('message')
    if not isinstance(msg, dict) or msg.get('role') != 'assistant':
        continue
    usage = msg.get('usage') or {}
    ti += int(usage.get('input') or 0)
    to += int(usage.get('output') or 0)
    blocks = []
    for b in msg.get('content') or []:
        if not isinstance(b, dict):
            continue
        if b.get('type') == 'toolCall':
            inp = dict(b.get('arguments') or {})
            if 'path' in inp and 'file_path' not in inp:
                inp['file_path'] = inp['path']
            blocks.append({'type': 'tool_use', 'name': b.get('name'), 'input': inp})
        elif b.get('type') == 'text':
            blocks.append({'type': 'text', 'text': b.get('text') or ''})
    print(json.dumps({'type': 'assistant',
                      'message': {'role': 'assistant', 'content': blocks,
                                  'usage': {'input_tokens': ti, 'output_tokens': to}}}))
print(json.dumps({'type': 'result', 'usage': {'input_tokens': ti, 'output_tokens': to}}))
if proc.stderr:
    sys.stderr.write(proc.stderr.decode('utf-8', 'replace')[-2000:])
sys.exit(proc.returncode)
